// === Tab: mySketch ===
var snk = [[0,0, 0],
          [0,0, 0.2],
          [0,0, 0.4],
          [0,0, 0.6],
          [0,0, 0.8],
          [0,0, 0],
          [0,0, 0.2],
          [0,0, 0.4],
          [0,0, 0.6],
          [0,0, 0.8],
					[0,0, 0],
          [0,0, 0.2],
          [0,0, 0.4],
          [0,0, 0.6],
          [0,0, 0.8]];
var jump = 10;

function setup() {
  createCanvas(800, 800);
  frameRate(120);
  background(255);
  colorMode(HSB, 100);
  noStroke();
  for (let i of snk) {
    i[0] = random(0,width)%jump;
    i[0] -= i[0]%jump;
    i[1] = random(0,height)%jump;
    i[1] -= i[1]%jump;
  }
}

function draw() {
  background(166, 0, 100, 3); // 5 est pas mal

  stroke(50);
  for (let t=0; t<25; t++) {

    for (let i of snk) {

      if (random()<0.5) {
        if (random()<0.5) {
          i[0] += jump;
        }else{
          i[0] -= jump;
        }
      }else{
        if (random()<0.5) {
          i[1] += jump;
        }else{
          i[1] -= jump;
        }
      }

      if (i[0] > width) i[0] = 0;
      if (i[1] > height) i[1] = 0;
      if (i[0] < 0) i[0] = width;
      if (i[1] < 0) i[1] = height;

      i[2]+=0.001;
      if (i[2] >= 1) i[2] = 0;

      fill(180*i[2], 30, 99);
      rect(i[0], i[1], 20, 20);

    }

  }

  fill(166, 0, 100, 80);
  noStroke();

  triangle(0,150, 200, height-250, 0,height-250);
  triangle(0,150, width/2, 150, 200, height-250);
  triangle(width/2, 150, width, 150, width-200, height-250);
  triangle(width, height-250, width, 150, width-200, height-250);
  rect(0,0,width, 150);
  rect(0,height-250, width, 250);
  noFill();
  stroke(50);
  circle(width/2, height/2, 500);
  rect(width/2, height/2, 250, 250);

  //filter(BLUR, 5);
  //// noLoop() removed for animation

}
